-- Local-only behavioural security and correctness gate for IEOS Stage 4.
begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(92);

set local role anon;
select ieos_stage1_test.claim(null, 'anon');
select extensions.ok(not ieos_stage1_test.probe('select count(*) from public.master_files'), 'T01 [ANON] master-file rows are denied');
select extensions.ok(not has_function_privilege('anon', 'public.search_master_files(text,uuid,uuid,text,uuid,text,text,text,boolean,boolean,uuid,integer)', 'EXECUTE'), 'T02 [ANON] search RPC is denied');
select extensions.ok(not has_function_privilege('anon', 'public.create_master_file(text,uuid,uuid,text,text,uuid,text,text,text,text,text,text,boolean,text,uuid,boolean)', 'EXECUTE'), 'T03 [ANON] create RPC is denied');
select extensions.ok(not ieos_stage1_test.probe('select count(*) from public.master_file_settings'), 'T04 [ANON] settings are denied');
select extensions.ok(not ieos_stage1_test.probe('select count(*) from public.master_file_review'), 'T05 [ANON] cleanup view is denied');
reset role;

set local role authenticated;
select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000002', 'authenticated');
select extensions.ok(public.fn_mf_can_use(auth.uid()), 'T06 [MANAGER] active identity can use the register');
select extensions.is((select count(*)::bigint from public.master_file_settings), 1::bigint, 'T07 [MANAGER] one bounded verification setting is visible');
select extensions.is((select count(*)::bigint from public.master_files where file_number like 'MF-TEST-%'), 11::bigint, 'T08 [MANAGER] scoped fixture rows are visible');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000006'), 0::bigint, 'T09 [CROSS BU] foreign record is absent');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000005'), 0::bigint, 'T10 [P&C] unappointed manager cannot see restricted metadata');
select extensions.ok(exists(select 1 from public.master_files where id='77000000-0000-0000-0000-000000000004'), 'T11 [APPOINTED] explicitly appointed manager sees record');
select extensions.ok(not exists(select 1 from public.search_master_files(p_include_history=>false) where id='77000000-0000-0000-0000-000000000009'), 'T12 [DEFAULT SEARCH] superseded history is excluded');
select extensions.ok(exists(select 1 from public.search_master_files(p_include_history=>true) where id='77000000-0000-0000-0000-000000000009'), 'T13 [HISTORY] authorised search can include superseded records');
select extensions.is((select count(*)::bigint from public.search_master_files(p_category_slug=>'proposal')), 1::bigint, 'T14 [CATEGORY FILTER] category is applied server-side');
select extensions.ok(not exists(select 1 from public.search_master_files(p_owner_profile_id=>'71000000-0000-0000-0000-000000000003') where owner_profile_id<>'71000000-0000-0000-0000-000000000003'), 'T15 [OWNER FILTER] owner filter is applied server-side');
select extensions.ok((select count(*) > 0 from public.search_master_files(p_project_reference=>'Stage 4 Campaign')), 'T16 [PROJECT FILTER] project reference is applied server-side');
select extensions.ok(exists(select 1 from public.master_file_review where id='77000000-0000-0000-0000-000000000007' and 'MISSING MASTER LINK'=any(review_flags)), 'T17 [REVIEW] missing master link is flagged');
select extensions.ok(exists(select 1 from public.master_file_review where id='77000000-0000-0000-0000-000000000008' and 'DUPLICATE CANDIDATE'=any(review_flags)), 'T18 [REVIEW] duplicate candidate is flagged');
select extensions.ok(exists(select 1 from public.master_file_review where id='77000000-0000-0000-0000-000000000012' and 'SUPERSEDED FILE STILL CURRENT'=any(review_flags)), 'T19 [REVIEW] unresolved replacement status is flagged');
select extensions.ok(exists(select 1 from public.master_file_review where id='77000000-0000-0000-0000-000000000011' and 'NOT VERIFIED'=any(review_flags)), 'T20 [REVIEW] stale verification is flagged from configuration');
select extensions.is((select master_url from public.search_master_files(p_file_id=>'77000000-0000-0000-0000-000000000001')), 'https://docs.google.com/document/d/stage4-guide'::text, 'T21 [LINK] permitted master URL is returned');
select extensions.ok(not ieos_stage1_test.execute_ok($test$insert into public.master_files(file_name,business_unit_id,department_id,category_slug,owner_profile_id,master_url,created_by) values ('Direct write','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other','71000000-0000-0000-0000-000000000003','https://example.test/direct','71000000-0000-0000-0000-000000000002')$test$), 'T22 [DIRECT WRITE] client insert is denied');
select extensions.ok(not ieos_stage1_test.execute_ok($test$update public.master_files set remarks='forged' where id='77000000-0000-0000-0000-000000000001'$test$), 'T23 [DIRECT WRITE] client update is denied');
select extensions.ok(not ieos_stage1_test.execute_ok($test$delete from public.master_files where id='77000000-0000-0000-0000-000000000001'$test$), 'T24 [RETENTION] client delete is denied');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.create_master_file('Manager Canva Asset','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','design_artwork','Synthetic manager-created asset.','71000000-0000-0000-0000-000000000003','operational','current','https://www.canva.com/design/manager-created',null,null,'Stage 4 Campaign',false,null,null,true)$test$), 'T25 [CREATE] scoped manager can create an operational record');
select extensions.is((select source_system from public.master_files where file_name='Manager Canva Asset'), 'canva'::text, 'T26 [PROVIDER] Canva provider is inferred safely');
select extensions.is((select created_by from public.master_files where file_name='Manager Canva Asset'), '71000000-0000-0000-0000-000000000002'::uuid, 'T27 [IDENTITY] creator derives from Auth');
select extensions.ok(exists(select 1 from public.master_file_events e join public.master_files f on f.id=e.master_file_id where f.file_name='Manager Canva Asset' and e.event_type='created' and e.actor_id='71000000-0000-0000-0000-000000000002'), 'T28 [AUDIT] create event uses authenticated actor');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Missing Link Record','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other',null,'71000000-0000-0000-0000-000000000003','operational','current',null,null,null,null,false,null,null,true)$test$), 'T29 [CURRENT LINK] current record requires a usable URL');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Campaign FINAL2','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other',null,'71000000-0000-0000-0000-000000000003','operational','current','https://example.test/name',null,null,null,false,null,null,true)$test$), 'T30 [NAMING] unsafe version filename is rejected');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Unconfirmed Record','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other',null,'71000000-0000-0000-0000-000000000003','operational','under_review',null,null,null,null,false,null,null,false)$test$), 'T31 [DATA HANDLING] confirmation is mandatory');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Unsafe Secret Record','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other','Password: Secret123','71000000-0000-0000-0000-000000000003','operational','under_review',null,null,null,null,false,null,null,true)$test$), 'T32 [PASSWORD] obvious secret assignment is rejected');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Social Media Operating Guide','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','sop',null,'71000000-0000-0000-0000-000000000003','operational','current','https://example.test/collision',null,null,null,false,null,null,true)$test$), 'T33 [ONE CURRENT] duplicate current purpose is rejected');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Manager Restricted Record','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','hr',null,'71000000-0000-0000-0000-000000000003','pc_restricted','current','https://example.test/restricted',null,null,null,false,null,null,true)$test$), 'T34 [P&C ACTION] manager cannot create restricted metadata');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.link_master_file_task('77000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002')$test$), 'T35 [TASK LINK] manager can link a permitted task');
select extensions.is((select count(*)::bigint from public.master_file_tasks where master_file_id='77000000-0000-0000-0000-000000000001'), 2::bigint, 'T36 [TASK LINK] many task relationships are retained');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.link_master_file_artifact('77000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001')$test$), 'T37 [ARTIFACT LINK] permitted artifact link is idempotent');
select extensions.is((select count(*)::bigint from public.master_file_artifacts where master_file_id='77000000-0000-0000-0000-000000000001'), 1::bigint, 'T38 [ARTIFACT LINK] artifact promotion relationship is preserved');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.grant_master_file_access('77000000-0000-0000-0000-000000000004','71000000-0000-0000-0000-000000000004','appointed_personnel')$test$), 'T39 [APPOINT] manager can appoint an in-scope user');
select extensions.ok(exists(select 1 from public.master_file_access_grants where master_file_id='77000000-0000-0000-0000-000000000004' and profile_id='71000000-0000-0000-0000-000000000004'), 'T40 [APPOINT] explicit grant is visible to its manager');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.revoke_master_file_access('77000000-0000-0000-0000-000000000004','71000000-0000-0000-0000-000000000004','appointed_personnel')$test$), 'T41 [REVOKE] manager can revoke an explicit appointment');
select extensions.ok(not exists(select 1 from public.master_file_access_grants where master_file_id='77000000-0000-0000-0000-000000000004' and profile_id='71000000-0000-0000-0000-000000000004'), 'T42 [REVOKE] revoked grant is absent');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.verify_master_file('77000000-0000-0000-0000-000000000011')$test$), 'T43 [VERIFY] manager can verify a scoped record');
select extensions.ok((select last_verified_at > now()-interval '1 minute' from public.master_files where id='77000000-0000-0000-0000-000000000011'), 'T44 [VERIFY] verification timestamp is refreshed');
select extensions.ok(exists(select 1 from public.master_file_events where master_file_id='77000000-0000-0000-0000-000000000011' and event_type='verified'), 'T45 [VERIFY AUDIT] verification is audited');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.update_master_file_metadata((select id from public.master_files where file_name='Manager Canva Asset'),'Manager Canva Asset','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','design_artwork','Updated description.','71000000-0000-0000-0000-000000000003','operational','https://www.canva.com/design/manager-created','https://drive.google.com/drive/folders/manager-created',null,'Stage 4 Campaign',false,'Metadata reviewed.',true)$test$), 'T46 [EDIT] manager can update governed metadata');
select extensions.ok(exists(select 1 from public.master_files where file_name='Manager Canva Asset' and remarks='Metadata reviewed.' and row_version=2), 'T47 [EDIT] metadata update increments row version');
select extensions.ok(exists(select 1 from public.master_file_events e join public.master_files f on f.id=e.master_file_id where f.file_name='Manager Canva Asset' and e.event_type='metadata_updated'), 'T48 [EDIT AUDIT] metadata edit is audited');
reset role;

set local role authenticated;
select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000003', 'authenticated');
select extensions.is((select count(*)::bigint from public.master_files where file_number like 'MF-TEST-%'), 11::bigint, 'T49 [STAFF] scoped permitted fixture rows are visible');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000003'), 0::bigint, 'T50 [STAFF] management-only record is hidden');
select extensions.ok(exists(select 1 from public.master_files where id='77000000-0000-0000-0000-000000000004'), 'T51 [STAFF] appointed record is visible with explicit owner grant');
select extensions.ok(exists(select 1 from public.master_files where id='77000000-0000-0000-0000-000000000005'), 'T52 [STAFF] P&C record is visible only with explicit grant');
select extensions.is((select master_url from public.search_master_files(p_file_id=>'77000000-0000-0000-0000-000000000005')), 'https://drive.google.com/file/d/stage4-restricted'::text, 'T53 [P&C LINK] explicitly authorised staff receives restricted link');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.set_master_file_status('77000000-0000-0000-0000-000000000001','archived')$test$), 'T54 [STAFF ACTION] staff cannot change governed status');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.upsert_master_file_category('staff_attempt','Staff Attempt',500,true)$test$), 'T55 [CATEGORY] staff cannot configure categories');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000006'), 0::bigint, 'T56 [STAFF SCOPE] foreign business-unit record is hidden');
reset role;

set local role authenticated;
select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000004', 'authenticated');
select extensions.is((select count(*)::bigint from public.master_files where file_number like 'MF-TEST-%'), 8::bigint, 'T57 [INTERN] only operational fixture rows in scope are visible');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000002'), 0::bigint, 'T58 [INTERN] full-time record is hidden');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000003'), 0::bigint, 'T59 [INTERN] management record is hidden');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000004'), 0::bigint, 'T60 [INTERN] revoked appointed record is hidden');
select extensions.is((select count(*)::bigint from public.master_files where id='77000000-0000-0000-0000-000000000005'), 0::bigint, 'T61 [INTERN] P&C filename and metadata are hidden');
select extensions.is((select count(*)::bigint from public.search_master_files(p_search=>'Restricted Contract')), 0::bigint, 'T62 [SEARCH LEAK] restricted filename cannot be discovered');
select extensions.is((select master_url from public.search_master_files(p_file_id=>'77000000-0000-0000-0000-000000000001')), 'https://docs.google.com/document/d/stage4-guide'::text, 'T63 [INTERN LINK] permitted operational link is available');
select extensions.is((select count(*)::bigint from public.master_file_tasks where master_file_id='77000000-0000-0000-0000-000000000001'), 1::bigint, 'T64 [TASK RELATION] only the intern-visible related task is exposed');
select extensions.is((select count(*)::bigint from public.master_file_artifacts where master_file_id='77000000-0000-0000-0000-000000000001'), 0::bigint, 'T65 [ARTIFACT LEAK] full-time artifact relationship is hidden');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Intern File','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other',null,'71000000-0000-0000-0000-000000000004','operational','current','https://example.test/intern',null,null,null,false,null,null,true)$test$), 'T66 [INTERN ACTION] intern cannot create register records');
reset role;

set local role authenticated;
select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000006', 'authenticated');
select extensions.is((select count(*)::bigint from public.master_files), 0::bigint, 'T67 [INACTIVE] inactive user sees no register rows');
reset role;

set local role authenticated;
select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000005', 'authenticated');
select extensions.is((select count(*)::bigint from public.master_files), 0::bigint, 'T68 [UNASSIGNED] user without scope sees no register rows');
reset role;

set local role authenticated;
select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000001', 'authenticated');
select extensions.is((select count(*)::bigint from public.master_files where file_number like 'MF-TEST-%'), 13::bigint, 'T69 [DIRECTOR] all fixture metadata is visible globally');
select extensions.ok(exists(select 1 from public.master_files where id='77000000-0000-0000-0000-000000000006'), 'T70 [DIRECTOR] foreign business-unit record is visible');
select extensions.ok(exists(select 1 from public.master_files where id='77000000-0000-0000-0000-000000000005'), 'T71 [DIRECTOR] P&C record is visible');
select extensions.is((select master_url from public.search_master_files(p_search=>'Restricted Contract')), 'https://drive.google.com/file/d/stage4-restricted'::text, 'T72 [DIRECTOR LINK] P&C link is available to Director');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.grant_master_file_access('77000000-0000-0000-0000-000000000005','71000000-0000-0000-0000-000000000004','pc_restricted')$test$), 'T73 [P&C GRANT] intern cannot receive P&C access');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.upsert_master_file_category('policy_note','Policy Note',195::smallint,true)$test$), 'T74 [CATEGORY CONFIG] Director can add a controlled category');
select extensions.ok(exists(select 1 from public.master_file_categories where slug='policy_note' and label='Policy Note'), 'T75 [CATEGORY CONFIG] configured category is available');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.create_master_file('Password Vault Reference','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other','Reference to approved storage only.','71000000-0000-0000-0000-000000000003','pc_restricted','current','https://example.test/vault-reference',null,'website',null,true,'Contains no credential value.',null,true)$test$), 'T76 [PASSWORD REFERENCE] Director can register a restricted storage reference');
select extensions.ok(exists(select 1 from public.master_file_access_grants g join public.master_files f on f.id=g.master_file_id where f.file_name='Password Vault Reference' and g.profile_id='71000000-0000-0000-0000-000000000003' and g.grant_type='pc_restricted'), 'T77 [OWNER GRANT] restricted owner receives explicit access');
select extensions.ok(not ieos_stage1_test.execute_ok($test$select public.create_master_file('Unsafe Password Reference','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','other',null,'71000000-0000-0000-0000-000000000003','operational','current','https://example.test/bad-reference',null,null,null,true,null,null,true)$test$), 'T78 [PASSWORD REFERENCE] non-P&C password reference is rejected');
select extensions.ok(exists(select 1 from public.master_file_events e join public.master_files f on f.id=e.master_file_id where f.file_name='Password Vault Reference' and e.actor_id='71000000-0000-0000-0000-000000000001'), 'T79 [AUDIT IDENTITY] restricted create actor derives from Auth');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.create_master_file('Supersede Source Record','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','form',null,'71000000-0000-0000-0000-000000000003','operational','current','https://example.test/supersede-old',null,null,null,false,null,null,true)$test$), 'T80 [SUPERSEDE SETUP] source record is created');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.create_master_file('Supersede Replacement Record','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','form',null,'71000000-0000-0000-0000-000000000003','operational','under_review','https://example.test/supersede-new',null,null,null,false,null,null,true)$test$), 'T81 [SUPERSEDE SETUP] replacement record is created');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.supersede_master_file((select id from public.master_files where file_name='Supersede Source Record'),(select id from public.master_files where file_name='Supersede Replacement Record'))$test$), 'T82 [SUPERSEDE] replacement is atomic');
select extensions.ok(exists(select 1 from public.master_files where file_name='Supersede Source Record' and status='superseded'), 'T83 [SUPERSEDE] source is preserved as superseded');
select extensions.ok(exists(select 1 from public.master_files replacement join public.master_files source on source.id=replacement.supersedes_file_id where replacement.file_name='Supersede Replacement Record' and replacement.status='current' and source.status='superseded'), 'T84 [SUPERSEDE] current replacement points to preserved source');
select extensions.is((select count(*)::bigint from public.master_file_events e join public.master_files f on f.id=e.master_file_id where f.file_name in ('Supersede Source Record','Supersede Replacement Record') and e.event_type='superseded'), 2::bigint, 'T85 [SUPERSEDE AUDIT] both sides are audited');
select extensions.ok(ieos_stage1_test.execute_ok($test$select public.mark_master_file_duplicate('77000000-0000-0000-0000-000000000008','77000000-0000-0000-0000-000000000001')$test$), 'T86 [DUPLICATE] duplicate cleanup action succeeds');
select extensions.ok(exists(select 1 from public.master_files where id='77000000-0000-0000-0000-000000000008' and status='archived' and duplicate_of_file_id='77000000-0000-0000-0000-000000000001' and archive_date is not null), 'T87 [DUPLICATE] duplicate is retained and linked to canonical record');
select extensions.ok(exists(select 1 from public.master_file_events where master_file_id='77000000-0000-0000-0000-000000000008' and event_type='duplicate_marked'), 'T88 [DUPLICATE AUDIT] cleanup action is audited');
select extensions.ok(exists(select 1 from public.search_master_files(p_search=>'Supersede Source',p_include_history=>true) where status='superseded'), 'T89 [HISTORICAL SEARCH] superseded record remains searchable');
reset role;

select extensions.ok(not ieos_stage1_test.execute_ok($test$update public.master_file_events set metadata='{"forged":true}' where master_file_id='77000000-0000-0000-0000-000000000001'$test$), 'T90 [AUDIT IMMUTABILITY] audit events cannot be updated even by table owner');
select extensions.ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.master_file_review'::regclass), 'T91 [VIEW SECURITY] cleanup view is security invoker');
select extensions.ok((select prosecdef from pg_proc where oid='public.search_master_files(text,uuid,uuid,text,uuid,text,text,text,boolean,boolean,uuid,integer)'::regprocedure), 'T92 [SEARCH SECURITY] search RPC applies explicit visibility filtering as definer');

select * from extensions.finish();
rollback;
